<?php session_start();require 'conectare.php';$id=filter_input(INPUT_GET,'id_domeniu',FILTER_VALIDATE_INT)?:0;$s=$pdo->prepare('SELECT nume_domeniu FROM domenii WHERE id_domeniu=?');$s->execute([$id]);$domain=$s->fetch();if(!$domain){http_response_code(404);exit('Domeniu inexistent.');}$s=$pdo->prepare('SELECT c.id_carte,c.titlu,a.nume_autor,c.pret FROM carti c JOIN autori a ON a.id_autor=c.id_autor WHERE c.id_domeniu=? ORDER BY c.titlu');$s->execute([$id]);$books=$s->fetchAll();include 'page_top.php';include 'meniu.php';?><h1 class="page-title"><?=h($domain['nume_domeniu'])?></h1><div class="book-list"><?php foreach($books as $b):$bid=(int)$b['id_carte'];$img="./coperti/$bid.jpg"?><article class="book-row"><?php if(file_exists($img)):?><img src="<?=h($img)?>" alt=""><?php else:?><div class="mini-cover">Carte</div><?php endif;?><div><h3 class="book-title"><a href="carte.php?id_carte=<?=$bid?>"><?=h($b['titlu'])?></a></h3><div class="author"><?=h($b['nume_autor'])?></div></div><div class="price"><?=number_format((float)$b['pret'],2,',','.')?> lei</div></article><?php endforeach;?></div><?php include 'page_bottom.php';?>
